using System.Runtime.InteropServices;

namespace Legio.Protocol;

/// <summary>
/// Tessera (The Tablet/Tile).
/// Cache-line-sized (64-byte), blittable performance report generated by Centurions after processing a cohort phase.
/// </summary>
[StructLayout(LayoutKind.Sequential)]
public struct Tessera
{
    /// <summary>
    /// Total active execution duration of the reported work in Stopwatch ticks.
    /// </summary>
    public long DurationTicks;

    /// <summary>
    /// Total time in Stopwatch ticks this Centurion spent waiting at the phase barrier for straggler peers.
    /// </summary>
    public long BarrierWaitTicks;

    /// <summary>
    /// Active execution ticks accumulated on chunks located in the first half of the cohort buffer [0, N/2).
    /// </summary>
    public long FirstHalfTicks;

    /// <summary>
    /// Active execution ticks accumulated on chunks located in the second half of the cohort buffer [N/2, N).
    /// </summary>
    public long SecondHalfTicks;

    /// <summary>
    /// Number of items actually processed by this Centurion during this report.
    /// </summary>
    public int ItemCount;

    /// <summary>
    /// Total items scheduled for this Cohort in the frame (gives Oracle true workload scale).
    /// </summary>
    public int TotalCohortItems;

    /// <summary>
    /// ID of the Centurion (Thread) that performed the work.
    /// </summary>
    public int CenturioId;

    /// <summary>
    /// ID of the Cohort (System) reporting.
    /// </summary>
    public int CohortId;

    /// <summary>
    /// Number of successful work steals performed by this Centurion during this phase.
    /// </summary>
    public int StealCount;

    /// <summary>
    /// Number of CAS contentions experienced while stealing during this phase.
    /// </summary>
    public int ContentionCount;

    /// <summary>
    /// Current normalized CPU pressure [0.0 - 1.0] observed by Speculator.
    /// </summary>
    public float CpuPressure;

    /// <summary>
    /// Number of active Centurion threads participating in this phase.
    /// </summary>
    public int ActiveWorkers;
}